#include "intern/dxfparserlimits.h"
#include "dwg2dxf/dx_iface.h"
#include "dwg2dxf/dx_data.h"
#include <iostream>
#include <string>

struct Selected {
    const DRW_Attdef* definition=nullptr;
    const DRW_Insert* parent=nullptr;
    const DRW_Attrib* child=nullptr;
};
Selected select(const dx_data& data) {
    Selected out;
    for(const auto* block:data.blocks)if(block&&block->name=="ACadSharpPeer")
        for(const auto* entity:block->ent)if(const auto* value=dynamic_cast<const DRW_Attdef*>(entity))
            if(value->tag=="P4PEER") {if(out.definition)return {};out.definition=value;}
    if(data.mBlock)for(const auto* entity:data.mBlock->ent)
        if(const auto* parent=dynamic_cast<const DRW_Insert*>(entity))if(parent->name=="ACadSharpPeer") {
            if(out.parent)return {};out.parent=parent;
            for(const auto& value:parent->attlist)if(value&&value->tag=="P4PEER") {
                if(out.child)return {};out.child=value.get();
            }
        }
    return out;
}
class DxIfaceTableSourceTestAccess {
public:
    static void proof(const dx_data& data,const Selected& selected) {
        bool pair=false,replay=false;int reason=-1;std::size_t rejected=0u;
        const auto found=data.m_tableDxfSource.resources.find(selected.definition->handle);
        if(found!=data.m_tableDxfSource.resources.end()) {
            const auto& r=found->second;pair=r.attdefPairMatched;
            replay=r.attdefFieldsMatched&&!r.attdefFieldMismatch;
            reason=static_cast<int>(r.attdefProfile.reason);rejected=r.attdefProfile.rejectedGroup;
        }
        unsigned compounds=0u;bool modeled=false,profiles=false,space=false;int state=-1,childReason=-1;
        std::size_t childRejected=0u;
        for(const auto& owner:data.m_tableDxfSource.entitiesCompoundAudits)if(owner&&owner->physical)
            for(const auto& p:owner->proofs)if(p.compound&&p.first<owner->members.size()
                &&owner->members[p.first].self==selected.parent->handle) {
                ++compounds;modeled=p.modeledMatched;profiles=p.profilesMatched;space=p.spaceMatched;
                state=static_cast<int>(p.state);
                for(std::size_t i=p.first;i<p.next&&i<owner->members.size();++i)
                    if(owner->members[i].self==selected.child->handle&&i-p.first<p.profiles.size()) {
                        childReason=static_cast<int>(p.profiles[i-p.first].reason);
                        childRejected=p.profiles[i-p.first].rejectedGroup;
                    }
            }
        std::cout<<"{\"stage\":\"original-proof\",\"definitionPair\":"<<pair
            <<",\"definitionReplay\":"<<replay<<",\"definitionProfileReason\":"<<reason
            <<",\"definitionRejectedGroup\":"<<rejected<<",\"selectedCompounds\":"<<compounds
            <<",\"compoundModeled\":"<<modeled<<",\"compoundProfiles\":"<<profiles
            <<",\"compoundSpace\":"<<space<<",\"compoundState\":"<<state
            <<",\"childProfileReason\":"<<childReason<<",\"childRejectedGroup\":"<<childRejected<<"}\n";
    }
};
void point(const DRW_Coord& p) {std::cout<<'['<<p.x<<','<<p.y<<','<<p.z<<']';}
void observe(const char* stage,const Selected& s) {
    std::cout<<"{\"stage\":\""<<stage<<"\",\"definitionHandle\":"<<s.definition->handle
        <<",\"definitionOwner\":"<<s.definition->parentHandle<<",\"definitionAlign\":";
    point(s.definition->secPoint);std::cout<<",\"definitionEmbeddedInsertion\":";point(s.definition->mtext->basePoint);
    std::cout<<",\"definitionType\":"<<static_cast<unsigned>(s.definition->m_attributeType)
        <<",\"definitionVersion\":"<<static_cast<unsigned>(s.definition->attVersion)
        <<",\"parentHandle\":"<<s.parent->handle<<",\"childHandle\":"<<s.child->handle
        <<",\"childOwner\":"<<s.child->parentHandle<<",\"childAlign\":";
    point(s.child->secPoint);std::cout<<",\"childEmbeddedInsertion\":";point(s.child->mtext->basePoint);
    std::cout<<",\"childType\":"<<static_cast<unsigned>(s.child->m_attributeType)
        <<",\"childVersion\":"<<static_cast<unsigned>(s.child->attVersion)
        <<",\"footerHandle\":"<<s.parent->seqEndEntity->handle
        <<",\"footerOwner\":"<<s.parent->seqEndEntity->parentHandle<<"}\n";
}
bool ready(const Selected& s) {
    return s.definition&&s.parent&&s.child&&s.definition->mtext&&s.child->mtext
        &&s.parent->attlist.size()==1u&&s.parent->seqEndEntity;
}
bool equal(const DRW_Coord& p,double x,double y,double z) {return p.x==x&&p.y==y&&p.z==z;}
int main(int argc,char** argv) {
    if(argc!=4)return 2;
    if(std::string(argv[3])=="read") {
        for(bool binary:{false,true}) {
            const std::string path=std::string(argv[2])+(binary?"-bin.dxf":"-asc.dxf");
            dx_iface reader;dx_data result;if(!reader.fileImport(path,&result,false))return 8;
            const auto selected=select(result);if(!ready(selected))return 9;
            observe(binary?"binary-reimport":"ascii-reimport",selected);
            // This is a source/output discrepancy baseline, not correct behavior.
            if(!equal(selected.definition->secPoint,21,22,23)||!equal(selected.child->secPoint,41,42,43)
                ||!equal(selected.definition->mtext->basePoint,21,22,23)||!equal(selected.child->mtext->basePoint,41,42,43))return 10;
        }
        return 0;
    }
    if(std::string(argv[3])!="write")return 2;
    dx_iface input;dx_data source;if(!input.fileImport(argv[1],&source,false))return 3;
    const auto original=select(source);if(!ready(original))return 4;
    observe("original-import",original);DxIfaceTableSourceTestAccess::proof(source,original);
    if(!equal(original.definition->secPoint,11,12,13)||!equal(original.definition->mtext->basePoint,21,22,23)
        ||!equal(original.child->secPoint,31,32,33)||!equal(original.child->mtext->basePoint,41,42,43))return 5;
    for(bool binary:{false,true}) {
        const std::string path=std::string(argv[2])+(binary?"-bin.dxf":"-asc.dxf");
        dx_iface writer;if(!writer.fileExport(path,DRW::AC1032,binary,&source,true))return 6;
        if(!equal(original.definition->secPoint,11,12,13)||!equal(original.child->secPoint,31,32,33))return 7;
    }
    observe("source-model-after-both-exports",original);
    return 0;
}
